let fase = 'foco';
let faltam = duracao.foco;
let deadline = null;

function atualizar(agora = Date.now()) {
  if (deadline !== null) {
    faltam = Math.max(0, Math.ceil((deadline - agora) / 1000));
    if (faltam === 0) {
      fase = fase === 'foco' ? 'pausa' : 'foco';
      faltam = duracao[fase];
      deadline = null;
    }
  }
  const segundos = String(faltam % 60).padStart(2, '0');
  app.querySelector('output').textContent = fase + ' ' + Math.floor(faltam / 60) + ':' + segundos;
}

