async function buscarCidade(cidade, requisitar = fetch) {
  const geo = await requisitar('https://geocoding-api.open-meteo.com/v1/search?count=1&name=' + encodeURIComponent(cidade));
  if (!geo.ok) throw new Error('Busca indisponível');
  const local = (await geo.json()).results?.[0];
  if (!local) throw new Error('Cidade não encontrada');
  const url = new URL('https://api.open-meteo.com/v1/forecast');
  url.search = new URLSearchParams({ latitude: local.latitude, longitude: local.longitude, current: 'temperature_2m' });
  const previsao = await requisitar(url);
  if (!previsao.ok) throw new Error('Previsão indisponível');
  const temperatura = (await previsao.json()).current?.temperature_2m;
  if (typeof temperatura !== 'number') throw new Error('Previsão inválida');
  return local.name + ': ' + temperatura + ' °C';
}

