function criarEncurtador(links = {}, guardar = () => {}) {
  let id = Object.keys(links).length;
  return (metodo, caminho, dados = {}) => {
    if (metodo === 'POST' && caminho === '/links') {
      let url;
      try { url = new URL(dados.url); } catch { return [400, {erro:'URL inválida'}]; }
      if (!['http:', 'https:'].includes(url.protocol)) return [400, {erro:'Protocolo inválido'}];
      let chave;
      do { chave = (++id).toString(36); } while (Object.hasOwn(links, chave));
      links[chave] = url.href;
      guardar(links);
      return [201, { caminho: '/' + chave, destino: url.href }];
    }
    const chave = caminho.slice(1);
    if (metodo === 'GET' && Object.hasOwn(links, chave)) return [302, null, { Location: links[chave] }];
    return [404, {erro:'Link não encontrado'}];
  };
}
if (typeof module !== 'undefined') module.exports = criarEncurtador;

