def executar(operacao, numeros):
    if not numeros:
        raise ValueError('Informe números')
    if operacao == 'ordenar':
        dados = list(numeros)
        for indice in range(1, len(dados)):
            valor, posicao = dados[indice], indice
            while posicao and dados[posicao - 1] > valor:
                dados[posicao] = dados[posicao - 1]
                posicao -= 1
            dados[posicao] = valor
        return dados
    if operacao == 'mdc':
        if len(numeros) != 2:
            raise ValueError('O MDC recebe dois números')
        a, b = map(abs, numeros)
        while b:
            a, b = b, a % b
        return a
    alvo, *dados = numeros
    dados = sorted(dados)
    inicio, fim = 0, len(dados)
    while inicio < fim:
        meio = (inicio + fim) // 2
        if dados[meio] < alvo:
            inicio = meio + 1
        else:
            fim = meio
    return inicio if inicio < len(dados) and dados[inicio] == alvo else -1

def main(args=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('operacao', choices=['buscar', 'ordenar', 'mdc'])
    parser.add_argument('numeros', nargs='+', type=int)
    op = parser.parse_args(args)
    return executar(op.operacao, op.numeros)

def quadro(tempo, largura=61, altura=23):
    linhas = []
    for y in range(altura):
        linha = []
        for x in range(largura):
            dx, dy = (x - largura // 2) * 0.5, y - altura // 2
            raio = math.hypot(dx, dy)
            if 3 <= raio <= 10:
                angulo = math.atan2(dy, dx) + tempo / raio ** 0.5
                luminosidade = (math.cos(angulo * 3) + 1) / 2
                linha.append('.:*#@'[int(luminosidade * 4)])
            else:
                linha.append(' ')
        linhas.append(''.join(linha))
    return '\n'.join(linhas)

def main():
    import time
    for frame in range(80):
        print('\033[H\033[J' + quadro(frame / 4), flush=True)
        time.sleep(0.08)
    return ''

class Mundo:
    def __init__(self, limite):
        self.entidades = [None] * limite

def criar(self, posicao, velocidade, raio):
    for i, item in enumerate(self.entidades):
        if item is None:
            self.entidades[i] = (posicao, velocidade, raio)
            return i
    return None

def passo(self, dt):
    ativos = []
    for i, item in enumerate(self.entidades):
        if item is None:
            continue
        (x, y), (vx, vy), raio = item
        pos = (x + vx * dt, y + vy * dt)
        self.entidades[i] = (pos, (vx, vy), raio)
        ativos.append((i, pos, raio))
    return [(a, b) for k, (a, p, r) in enumerate(ativos)
            for b, q, s in ativos[k+1:] if math.dist(p, q) <= r + s]

def main():
    mundo = Mundo(2)
    mundo.criar((0, 0), (1, 0), 0.5)
    mundo.criar((3, 0), (-1, 0), 0.5)
    return mundo.passo(1)

